from pathlib import Path
source=Path('work/booking_browser.mjs').read_text(encoding='utf-8')
prefix=source[:source.index("  await admin.goto(adminUrl+'/services');")]
prefix=prefix.replace('academy_test_booking_ui_','academy_test_schedule_ui_').replace('outputs/booking-linkage-2026-10-12','outputs/booking-schedule-2026-10-12')
tail=source[source.index('}catch(error){'):]
body=r'''
  const offering=await bookings.saveOffering(req,{teacherId:teacher.id,title:'经典研习交流',mode:'PHONE',durationMinutes:30,leadMinutes:0,cancelBeforeMinutes:2880,locationPolicy:'老师按预约电话联系',deliveryPolicy:'交流经典阅读疑问，梳理后续研习方法。',price:0,active:true});
  await bookings.createSlot(req,offering.id,{startsAt:new Date(Date.now()+day).toISOString()});
  await mobile.goto(mobileUrl+'/#/pages/auth/login');await mobile.locator('input').nth(0).fill('19900001002');const sms=pending(mobile.waitForResponse(r=>r.url().endsWith('/auth/sms')&&r.request().method()==='POST'));await mobile.getByText('获取验证码',{exact:true}).click();assert.equal((await sms).status(),201);await mobile.getByText(/秒后重发/).waitFor();await mobile.locator('input').nth(1).fill('123456');await mobile.locator('.consent-touch').click();const logged=pending(mobile.waitForResponse(r=>r.url().endsWith('/auth/login')&&r.request().method()==='POST'));await mobile.locator('.login-submit').click();assert.equal((await logged).status(),200);
  await appPage('teacher/detail?id='+teacher.id);await mobile.getByText('查看咨询与见面时段',{exact:true}).click();await mobile.locator('.time-choice').first().click();await mobile.locator('.booking-input input').nth(0).fill('共学体验学员');await mobile.locator('.booking-input input').nth(1).fill('19900001002');await mobile.locator('.consent-button').click();const appointmentSaved=pending(mobile.waitForResponse(r=>r.url().endsWith('/appointments')&&r.request().method()==='POST'));await mobile.getByText('确认预约',{exact:true}).click();assert.equal((await appointmentSaved).status(),201);await mobile.locator('.booking-card').getByText(offering.title,{exact:true}).waitFor();assert.equal(await mobile.getByText('取消预约',{exact:true}).count(),0);
  checks.push('App原预约按冻结规则已过取消截止，未展示非法取消按钮');
  async function refreshMine(){await appPage('teacher/detail?id='+teacher.id);await mobile.getByText('查看咨询与见面时段',{exact:true}).waitFor();await appPage('booking/mine');await mobile.locator('.booking-card').first().waitFor();}
  async function submitChange(eventMode,offset,reason){
    await admin.getByRole('button',{name:'延期',exact:true}).click();const start=admin.getByLabel('新开始时间（北京时间）',{exact:true});await start.fill(beijing(Date.now()+offset*day));await start.press('Enter');if(eventMode){const end=admin.getByLabel('新结束时间（北京时间）',{exact:true});await end.fill(beijing(Date.now()+offset*day+7200000));await end.press('Enter');await admin.getByLabel('新场地',{exact:true}).fill('二楼共读室');}
    await admin.getByLabel('通知学员的原因',{exact:true}).fill(reason);const result=pending(admin.waitForResponse(r=>r.url().endsWith('/reschedule')&&r.request().method()==='POST'));await admin.getByRole('button',{name:'保存延期',exact:true}).click();assert.equal((await result).status(),201);await admin.locator('.ant-modal-content:visible').waitFor({state:'hidden'});
  }
  await admin.goto(adminUrl+'/services');await admin.getByRole('button',{name:'统一时段',exact:true}).click();await submitChange(false,3,'老师行程调整，服务顺延两日');await admin.locator('.ant-drawer-content-wrapper:visible').screenshot({path:output+'/admin-service-delayed.png'});
  await refreshMine();const appointmentCard=mobile.locator('.booking-card').filter({hasText:offering.title});await appointmentCard.getByText('待确认新安排',{exact:true}).waitFor();await appointmentCard.getByText('老师行程调整，服务顺延两日',{exact:true}).waitFor();await mobile.screenshot({path:output+'/app-service-pending.png',fullPage:true});
  await appointmentCard.getByText('确认新安排',{exact:true}).click();const accepted=pending(mobile.waitForResponse(r=>r.url().endsWith('/accept-schedule')&&r.request().method()==='POST'));await mobile.getByText('确认参加',{exact:true}).click();assert.equal((await accepted).status(),201);await appointmentCard.getByText('已确认',{exact:true}).waitFor();checks.push('Pro真实延期服务，App展示原时间/新安排/原因并实际确认');
  await submitChange(false,4,'再次调整，请重新确认');await refreshMine();await appointmentCard.getByText('待确认新安排',{exact:true}).waitFor();await appointmentCard.getByText('取消预约',{exact:true}).click();const cancelled=pending(mobile.waitForResponse(r=>r.url().endsWith('/cancel')&&r.request().method()==='POST'));await mobile.getByText('确认取消',{exact:true}).click();assert.equal((await cancelled).status(),201);await appointmentCard.getByText('已取消',{exact:true}).waitFor();checks.push('第二次延期使原确认失效，App可拒绝新安排且原记录保留');
  await appPage('event/detail?id='+event.id);await mobile.getByText('查看场次与报名',{exact:true}).click();await mobile.locator('.time-choice').first().click();await mobile.locator('.booking-input input').nth(0).fill('共读参加者');await mobile.locator('.booking-input input').nth(1).fill('19900001002');await mobile.locator('.consent-button').click();const registered=pending(mobile.waitForResponse(r=>r.url().endsWith('/registrations')&&r.request().method()==='POST'));await mobile.getByText('确认报名',{exact:true}).click();assert.equal((await registered).status(),201);await mobile.locator('.booking-card').filter({hasText:event.title}).waitFor();
  await admin.goto(adminUrl+'/events');await admin.getByRole('button',{name:'场次与报名',exact:true}).click();await submitChange(true,3,'共读室维护，改至二楼');await admin.getByRole('tab',{name:'报名与到场',exact:true}).click();await admin.getByText('待学员确认改期',{exact:true}).waitFor();assert.equal(await admin.getByRole('button',{name:'第1位到场',exact:true}).count(),0);checks.push('Pro实际延期活动并隐藏未确认学员的签到动作');
  await refreshMine();const eventCard=mobile.locator('.booking-card').filter({hasText:event.title});await eventCard.getByText('待确认新安排',{exact:true}).waitFor();await eventCard.getByText(/二楼共读室/).waitFor();await mobile.screenshot({path:output+'/app-event-pending.png',fullPage:true});await eventCard.getByText('确认新安排',{exact:true}).click();const eventAccepted=pending(mobile.waitForResponse(r=>r.url().endsWith('/accept-schedule')&&r.request().method()==='POST'));await mobile.getByText('确认参加',{exact:true}).click();assert.equal((await eventAccepted).status(),201);await eventCard.getByText('已确认',{exact:true}).waitFor();checks.push('App查看活动新地点与原时间并真实确认');
  await admin.getByRole('tab',{name:'场次与库存',exact:true}).click();await admin.getByRole('button',{name:'取消场次',exact:true}).click();await admin.getByLabel('通知学员的原因',{exact:true}).fill('书院安排调整，本次共读取消');const eventCancelled=pending(admin.waitForResponse(r=>r.url().endsWith('/cancel')&&r.request().method()==='POST'));await admin.locator('.ant-modal-footer').getByRole('button',{name:'确认取消',exact:true}).click();assert.equal((await eventCancelled).status(),201);await admin.getByText('已取消',{exact:true}).waitFor();await admin.locator('.ant-drawer-content-wrapper:visible').screenshot({path:output+'/admin-event-cancelled.png'});
  await bookings.runNoticeJobs();await refreshMine();await eventCard.getByText('已取消',{exact:true}).waitFor();await eventCard.getByText('书院安排调整，本次共读取消',{exact:true}).waitFor();assert.equal(await eventCard.getByText('确认新安排',{exact:true}).count(),0);assert.equal(await eventCard.getByText('取消报名',{exact:true}).count(),0);await mobile.screenshot({path:output+'/app-event-cancelled.png',fullPage:true});checks.push('Pro取消整个场次，App同步取消状态/原因并移除非法动作');
  await appPage('profile/messages');await mobile.getByText('预约 / 活动已取消',{exact:true}).waitFor();await mobile.getByText('预约 / 活动已取消',{exact:true}).click();await mobile.locator('.booking-card').filter({hasText:event.title}).getByText('已取消',{exact:true}).waitFor();checks.push('持久消息实际送达，可从消息跳转查看取消记录');
  assert.equal(errors.length,0,JSON.stringify(errors));
'''
Path('work/booking_schedule_browser.mjs').write_text(prefix+body+tail,encoding='utf-8')
